## Code That Runs During Compilation

```xiom
comptime fn factorial(n: Int) -> Int {
  if n <= 1 { return 1; }
  return n * factorial(n - 1);
}

const RESULT: Int = comptime factorial(10);
// 3628800 — computed at compile time, baked into binary
```

### Comptime Blocks

```xiom
const CONFIG: Config = comptime {
  let file = include_str!("config.toml");
  return parse_config(file);  // Parsed at compile time!
};

fn main() {
  // CONFIG is a hard-coded constant — zero runtime parsing
  start_server(CONFIG);
}
```

### Comptime Type Generation

```xiom
comptime fn generate_table(n: Int) -> Type {
  var fields = Vec[Field]();
  for i in 0..n {
    fields.push(Field{ name: "col" + i.to_str(), type: Int });
  }
  return make_struct_type("Table", fields);
}

// Generate a struct with 10 Int fields at compile time
comptime {
  let Table10 = generate_table(10);
  // Table10{ col0, col1, col2, ..., col9 }
}
```

### Comptime Validation

```xiom
comptime fn assert_power_of_two(n: Int) {
  if n & (n - 1) != 0 {
    @comptime_error("Expected power of two, got: " + n.to_str());
  }
}

const BUFFER_SIZE: Int = 256;
comptime assert_power_of_two(BUFFER_SIZE);  // Checked at compile time!
```

### Comptime vs Runtime

```xiom
// Runtime: computed every function call
fn runtime_area(r: Float64) -> Float64 {
  return 3.14159 * r * r;
}

// Comptime: computed once, baked into binary
const CIRCLE_AREA_5: Float64 = comptime 3.14159 * 5.0 * 5.0;
```

