solution:
comptime fn sum_of_squares(n: Int) -> Int {
  var sum = 0;
  for i in 1..=n {
    sum = sum + i * i;
  }
  return sum;
}

const ANSWER: Int = comptime sum_of_squares(5);  // 55

fn main() -> Int {
  return ANSWER;
}
